package com.opensocket.aievent.database.persistence.a2a.repository;
import java.util.List; import java.util.Optional; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import com.opensocket.aievent.core.a2a.*; import com.opensocket.aievent.database.persistence.a2a.*; import com.opensocket.aievent.database.persistence.a2a.dao.*; import org.springframework.stereotype.Repository;
@Repository @ConditionalOnProperty(prefix="task",name="store",havingValue="MYBATIS") public class MybatisA2AStateHistoryRepository implements A2AStateHistoryRepository { private final A2AStateHistoryDao dao; private final A2APersistenceConverter c; public MybatisA2AStateHistoryRepository(A2AStateHistoryDao d,A2APersistenceConverter c){dao=d;this.c=c;} public A2AStateHistoryEntry save(A2AStateHistoryEntry v){dao.insert(c.toPo(v));return findByIdempotencyKey(v.getTenantId(),v.getIdempotencyKey()).orElse(v);} public Optional<A2AStateHistoryEntry> findByIdempotencyKey(String t,String k){return k==null?Optional.empty():Optional.ofNullable(dao.findByIdempotencyKey(t,k)).map(c::toDomain);} public List<A2AStateHistoryEntry> findByRequest(String t,String id,int n){return dao.findByRequest(t,id,Math.max(1,Math.min(n,1000))).stream().map(c::toDomain).toList();} public String mode(){return "MYBATIS";} }
